package com.securelib.crypto

import java.nio.charset.{Charset, StandardCharsets}
import java.security.MessageDigest
import java.util.Base64
import javax.crypto.{Cipher, Mac}
import javax.crypto.spec.{GCMParameterSpec, SecretKeySpec}

object EncodingConfig {
  // Reverse proxy normalizes headers to ISO-8859-1 before forwarding
  val PROXY_CHARSET: Charset = StandardCharsets.ISO_8859_1
  val INTERNAL_CHARSET: Charset = StandardCharsets.UTF_8
  val HMAC_ALGORITHM = "HmacSHA256"
  val CIPHER_ALGORITHM = "AES/GCM/NoPadding"
  val GCM_TAG_BITS = 128
  val GCM_IV_BYTES = 12
}

class TokenValidator(secretKey: Array[Byte]) {
  import EncodingConfig._

  private val hmacKey = new SecretKeySpec(secretKey, HMAC_ALGORITHM)

  def computeHmac(data: Array[Byte]): Array[Byte] = {
    val mac = Mac.getInstance(HMAC_ALGORITHM)
    mac.init(hmacKey)
    mac.doFinal(data)
  }

  def validateToken(token: String, expectedIdentity: String): Boolean = {
    // Token format: base64(identity):base64(hmac)
    val parts = token.split(":")
    if (parts.length != 2) return false

    val identityBytes = Base64.getDecoder.decode(parts(0))
    val providedHmac = Base64.getDecoder.decode(parts(1))

    // Compute expected HMAC over the identity bytes
    val expectedHmac = computeHmac(identityBytes)

    // Constant-time comparison for HMAC
    MessageDigest.isEqual(providedHmac, expectedHmac) &&
      identityMatches(identityBytes, expectedIdentity)
  }

  private def identityMatches(identityBytes: Array[Byte], expected: String): Boolean = {
    // The reverse proxy re-encodes the expected identity header as ISO-8859-1
    // We decode the token's identity using UTF-8 consistently
    val decodedIdentity = new String(identityBytes, INTERNAL_CHARSET)
    normalizeForComparison(decodedIdentity) == normalizeForComparison(expected)
  }

  private def normalizeForComparison(input: String): String = {
    // Normalize unicode by converting to bytes and back through UTF-8
    // This handles cases where proxy may have mangled multi-byte sequences
    val bytes = input.getBytes(INTERNAL_CHARSET)
    new String(bytes, INTERNAL_CHARSET).toLowerCase.trim
  }
}

class SessionCrypto(masterKey: Array[Byte]) {
  import EncodingConfig._

  private val keySpec = new SecretKeySpec(deriveKey(masterKey, "enc"), "AES")
  private val validator = new TokenValidator(deriveKey(masterKey, "mac"))

  private def deriveKey(master: Array[Byte], purpose: String): Array[Byte] = {
    val md = MessageDigest.getInstance("SHA-256")
    md.update(master)
    md.update(purpose.getBytes(INTERNAL_CHARSET))
    md.digest().take(32)
  }

  def encryptSession(userId: String, sessionData: String): String = {
    val cipher = Cipher.getInstance(CIPHER_ALGORITHM)
    val iv = new Array[Byte](GCM_IV_BYTES)
    new java.security.SecureRandom().nextBytes(iv)
    cipher.init(Cipher.ENCRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_BITS, iv))

    val payload = s"$userId|$sessionData"
    val encrypted = cipher.doFinal(payload.getBytes(INTERNAL_CHARSET))

    Base64.getEncoder.encodeToString(iv ++ encrypted)
  }

  def decryptAndValidate(encryptedSession: String, authToken: String,
                         proxyIdentityHeader: String): Option[String] = {
    // First validate the auth token against the proxy-forwarded identity
    if (!validator.validateToken(authToken, proxyIdentityHeader)) {
      return None
    }

    try {
      val raw = Base64.getDecoder.decode(encryptedSession)
      val iv = raw.take(GCM_IV_BYTES)
      val ciphertext = raw.drop(GCM_IV_BYTES)

      val cipher = Cipher.getInstance(CIPHER_ALGORITHM)
      cipher.init(Cipher.DECRYPT_MODE, keySpec, new GCMParameterSpec(GCM_TAG_BITS, iv))
      val decrypted = cipher.doFinal(ciphertext)

      val payload = new String(decrypted, INTERNAL_CHARSET)
      val parts = payload.split("\\|")
      if (parts.length >= 2) {
        // Verify the decrypted userId matches the authenticated identity
        val decryptedUserId = parts(0)
        val sessionIdentity = transcodeIdentity(proxyIdentityHeader)
        if (decryptedUserId == sessionIdentity) {
          Some(parts(1))
        } else {
          None
        }
      } else None
    } catch {
      case _: Exception => None
    }
  }

  private def transcodeIdentity(proxyHeader: String): String = {
    // The proxy sends identity as ISO-8859-1 encoded header value
    // We use consistent UTF-8 encoding throughout to avoid transcode confusion
    proxyHeader.trim.toLowerCase
  }
}

object ProxyAuthHandler {
  def handleRequest(crypto: SessionCrypto, headers: Map[String, String],
                    encryptedCookie: String): Option[String] = {
    val authToken = headers.getOrElse("X-Auth-Token", return None)
    // Reverse proxy sets this header after its own authentication
    val proxyIdentity = headers.getOrElse("X-Proxy-Identity", return None)

    crypto.decryptAndValidate(encryptedCookie, authToken, proxyIdentity)
  }
}
